EXCLUDED = {"fi-aalto": "tuition-fee page; the scholarship is one paragraph", "se-su-schol": "fees page, not a programme",
            "it-polimi-gold": "a 2024-25 call PDF listing several awards", "au-mwalimu": "generic page; the call is only in the title",
            "de-fes": "foundation overview without programme terms", "nz-vuw-tongarewa": "announcement that the programme ended"}
urls = json.loads((K / "urls.json").read_text())
ids = {p["id"] for p in urls["pages"]}
assert set(P) <= ids, set(P) - ids
# development split chosen before any scoring: the two known round-25 errors plus 6 drawn with seed 26
rest = sorted(k for k in P if not k.startswith("dev-"))
dev = set(random.Random(26).sample(rest, 6)) | {"dev-rhodes", "dev-jjwbgsp"}
pages = {}
for p in urls["pages"]:
    pid = p["id"]
    if pid in P:
        p["split"] = "dev" if pid in dev else "test"
        lab = P[pid]
        pages[pid] = {"kind": "opportunity", "fields": lab["fields"], "evidence": {k: {"quote": v, "url": p["url"]} for k, v in lab["evidence"].items()},
                      "ambiguous": lab.get("ambiguous", "")}
    else:
        p["split"] = "excluded"
        p["excluded_because"] = EXCLUDED.get(pid, "not a single-programme page (portal, list, home, login or empty)")
(K / "urls.json").write_text(json.dumps(urls, indent=1, ensure_ascii=False) + "\n")
(K / "labels.json").write_text(json.dumps({"today": "2026-10-18", "version": "K-1",
    "note": "programme fields labelled by hand from the official pages before any extractor ran on them; quotes per field",
    "pages": pages}, indent=1, ensure_ascii=False) + "\n")
print(len(pages), "labelled;", sum(1 for p in urls["pages"] if p["split"] == "test"), "test;", len(dev), "dev")
